865     sizeof( QueueHeader ) + sizeof( QueueStringTransfer ),  // allocated source location payload
866     sizeof( QueueHeader ) + sizeof( QueueStringTransfer ),  // callstack payload
867     sizeof( QueueHeader ) + sizeof( QueueStringTransfer ),  // callstack alloc payload
868     sizeof( QueueHeader ) + sizeof( QueueStringTransfer ),  // frame name
869     sizeof( QueueHeader ) + sizeof( QueueStringTransfer ),  // frame image data
870     sizeof( QueueHeader ) + sizeof( QueueStringTransfer ),  // external name
871     sizeof( QueueHeader ) + sizeof( QueueStringTransfer ),  // external thread name
872     sizeof( QueueHeader ) + sizeof( QueueStringTransfer ),  // symbol code
873     sizeof( QueueHeader ) + sizeof( QueueStringTransfer ),  // source code
874     sizeof( QueueHeader ) + sizeof( QueueStringTransfer ),  // fiber name
875 };
876 
877 static_assert( QueueItemSize == 32, "Queue item size not 32 bytes" );
878 static_assert( sizeof( QueueDataSize ) / sizeof( size_t ) == (uint8_t)QueueType::NUM_TYPES, "QueueDataSize mismatch" );
879 static_assert( sizeof( void* ) <= sizeof( uint64_t ), "Pointer size > 8 bytes" );
880 static_assert( sizeof( void* ) == sizeof( uintptr_t ), "Pointer size != uintptr_t" );
881 
882 }
883 
884 #endif
